function Main(
  list: () -> QueryResult,
  get: (id: string) -> Ticket?,
  close: (input: CloseInput) -> Ok,
  flaky: () -> (Success | Failure),
  read: () -> int,
  write: (value: int) -> void,
  increment: () -> void,
  query: (input: QueryInput) -> QueryResult
) -> int {
  let nums = [3, 1, 4, 1, 5]
  let odds = []int
  for (let n in nums) {
    if (n % 2 == 1) {
      odds.push(n)
    }
  }

  let i = 0
  while (i < odds.length) {
    let j = i + 1
    while (j < odds.length) {
      if (odds[j] < odds[i]) {
        let tmp = odds[i]
        odds[i] = odds[j]
        odds[j] = tmp
      }
      j = j + 1
    }
    i = i + 1
  }

  let sum = 0
  for (let n in odds) {
    sum = sum + n
  }
  sum
}

